				ctx.expect(tag_size>=8 and game.UI_FONT.get_string_size(tags,HORIZONTAL_ALIGNMENT_LEFT,-1,tag_size).x<=rect.size.x-8,"wayfinding second line fits real font width: "+locale+String(link.port))
